package local.tvmorph.tv;import org.json.*;public class XtreamEpgCheck{public static void main(String[] args)throws Exception{Xtream x=new Xtream(new JSONObject().put("server",args[0]).put("username","fixture").put("password","fixture"));JSONObject r=x.epg("42");JSONArray rows=r.getJSONArray("items");if(rows.length()!=2||!rows.getJSONObject(0).getString("title").equals("أخبار المساء")||!rows.getJSONObject(1).getString("title").equals("Plain title"))throw new AssertionError(r.toString());boolean rejected=false;try{x.epg("42&bad=1");}catch(Exception e){rejected=true;}if(!rejected)throw new AssertionError();System.out.println("PASS: actual native EPG request/UTF-8 decoding, plain-text fallback, timestamp checks and channel ID validation.");}}